window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-c127792a55cc0fae"]={"versions": [{"id": "FIG-c127792a55cc0fae", "releases": ["R4.2.2", "R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Aktivitäts- und Modellierungsdiagramm (Swimlane-Darstellung) im Kontext von AUTOSAR-Werkzeug-Interoperabilität (<code>AUTOSAR_RS_InteroperabilityOfAutosarTools</code>). Das Diagramm illustriert das Szenario des nebenläufigen Modellierens (<em>Concurrent modeling</em>) und die Aktualisierung von Modellelementen über Organisationsgrenzen hinweg. Zwei horizontale Verantwortungsbereiche (<em>Swimlanes</em>), <code>party X</code> und <code>Party Y</code>, stellen getrennte Modellierungsumgebungen bzw. Entwicklungspartner dar, die Modellelemente austauschen, aktualisieren und abgleichen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Swimlanes mit Package- und Element-Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Swimlane <code>party X</code>:</strong></li>\n<li>Package <code>Model A [source]</code> mit enthaltenem Modellelement <code>BrakControl[source]</code> (Schreibweise mit Tippfehler im Ausgangsmodell).</li>\n<li>Prozessschritt/Aktivität <code>Update</code>.</li>\n<li>Package <code>Model A [updated]</code> mit korrigiertem bzw. aktualisiertem Element <code>BrakeControl [updated]</code>.</li>\n<li><strong>Swimlane <code>Party Y</code>:</strong></li>\n<li>Package <code>Model A [remote]</code> mit enthaltenem referenziertem Element <code>BrakControl [remote]</code>.</li>\n<li>Package <code>Model B</code> mit lokalem Element <code>X</code>, das über eine Assoziations-/Referenzlinie mit <code>BrakControl [remote]</code> verknüpft ist.</li>\n<li>Package <code>Model A [merged]</code> mit integriertem Element <code>BrakeControl [merged]</code>.</li>\n<li>Package <code>Model B [merged]</code> mit Element <code>X [merged]</code>, das weiterhin mit <code>BrakeControl [merged]</code> verknüpft bleibt.</li>\n<li><strong>Schnittstellen / Relationen:</strong></li>\n<li>Gerichtete gestrichelte Pfeile für den Aktualisierungsfluss: von <code>BrakControl[source]</code> nach <code>Update</code> sowie von <code>Update</code> nach <code>BrakeControl [updated]</code>.</li>\n<li>Vertikale gestrichelte Abhängigkeitspfeile mit Stereotyp <code>«trace»</code> zwischen den Swimlanes:</li>\n<li>von <code>Model A [source]</code> nach <code>Model A [remote]</code>,</li>\n<li>von <code>Model A [updated]</code> nach <code>Model A [merged]</code>.</li>\n<li>Durchgezogene Referenzlinien innerhalb von <code>Party Y</code>: Verknüpfung zwischen Element <code>X</code> und dem referenzierten Modellteil <code>BrakControl</code> vor und nach dem Merge.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf stellt eine asynchrone Modellaktualisierung und -verschmelzung dar:</p>\n<ol class=\"fig-list\">\n<li><code>Party Y</code> verwendet eine lokale Kopie/Referenz <code>Model A [remote]</code> von <code>party X</code> und verknüpft eigene Modellelemente (<code>X</code> in <code>Model B</code>) mit <code>BrakControl [remote]</code>.</li>\n<li>Bei <code>party X</code> wird eine Aktualisierung (<code>Update</code>) am Ausgangselement durchgeführt, wodurch <code>BrakControl[source]</code> zu <code>BrakeControl [updated]</code> korrigiert bzw. modifiziert wird.</li>\n<li>Die Traceability (<code>«trace»</code>) stellt die Nachverfolgbarkeit zwischen Ursprungsmodell und Remote-Modell bzw. aktualisiertem Modell sicher.</li>\n<li>Das aktualisierte Modell wird an <code>Party Y</code> übermittelt und dort zu <code>Model A [merged]</code> zusammengeführt, wobei die bestehende interne Referenz von <code>X [merged]</code> auf das umbenannte/aktualisierte Element <code>BrakeControl [merged]</code> erhalten und aufgelöst wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dieses Schaubild verdeutlicht die funktionale Anforderung an AUTOSAR-Autorentools, semantisches Merging und Refactoring (z. B. Umbenennungen von AUTOSAR-Elementen wie Software-Komponenten, Ports oder Interfaces) über verteilte Arbeitsumgebungen hinweg konsistent zu unterstützen. Werkzeuge müssen Identitäten (z. B. über GUIDs / UUIDs oder stabile Pfade) beibehalten, damit Querreferenzen lokaler Artefakte (<code>Model B</code>) bei Aktualisierung extern verwalteter Pakete (<code>Model A</code>) nicht verwaisen (<em>dangling references</em>), sondern automatisiert auf den neuen Versionsstand umgebogen werden.</p>"}, {"id": "FIG-c82b5f1cee12f379", "releases": ["R18-10_R4.4.0_R1.5.0"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Aktivitäts- und Modellierungsdiagramm (Swimlane-Darstellung) im Kontext von AUTOSAR-Werkzeug-Interoperabilität (<code>AUTOSAR_RS_InteroperabilityOfAutosarTools</code>). Das Diagramm illustriert das Szenario des nebenläufigen Modellierens (<em>Concurrent modeling</em>) und die Aktualisierung von Modellelementen über Organisationsgrenzen hinweg. Zwei horizontale Verantwortungsbereiche (<em>Swimlanes</em>), <code>party X</code> und <code>Party Y</code>, stellen getrennte Modellierungsumgebungen bzw. Entwicklungspartner dar, die Modellelemente austauschen, aktualisieren und abgleichen.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert sich in zwei Swimlanes mit Package- und Element-Entitäten:</p>\n<ul class=\"fig-list\">\n<li><strong>Swimlane <code>party X</code>:</strong></li>\n<li>Package <code>Model A [source]</code> mit enthaltenem Modellelement <code>BrakControl[source]</code> (Schreibweise mit Tippfehler im Ausgangsmodell).</li>\n<li>Prozessschritt/Aktivität <code>Update</code>.</li>\n<li>Package <code>Model A [updated]</code> mit korrigiertem bzw. aktualisiertem Element <code>BrakeControl [updated]</code>.</li>\n<li><strong>Swimlane <code>Party Y</code>:</strong></li>\n<li>Package <code>Model A [remote]</code> mit enthaltenem referenziertem Element <code>BrakControl [remote]</code>.</li>\n<li>Package <code>Model B</code> mit lokalem Element <code>X</code>, das über eine Assoziations-/Referenzlinie mit <code>BrakControl [remote]</code> verknüpft ist.</li>\n<li>Package <code>Model A [merged]</code> mit integriertem Element <code>BrakeControl [merged]</code>.</li>\n<li>Package <code>Model B [merged]</code> mit Element <code>X [merged]</code>, das weiterhin mit <code>BrakeControl [merged]</code> verknüpft bleibt.</li>\n<li><strong>Schnittstellen / Relationen:</strong></li>\n<li>Gerichtete gestrichelte Pfeile für den Aktualisierungsfluss: von <code>BrakControl[source]</code> nach <code>Update</code> sowie von <code>Update</code> nach <code>BrakeControl [updated]</code>.</li>\n<li>Vertikale gestrichelte Abhängigkeitspfeile mit Stereotyp <code>«trace»</code> zwischen den Swimlanes:</li>\n<li>von <code>Model A [source]</code> nach <code>Model A [remote]</code>,</li>\n<li>von <code>Model A [updated]</code> nach <code>Model A [merged]</code>.</li>\n<li>Durchgezogene Referenzlinien innerhalb von <code>Party Y</code>: Verknüpfung zwischen Element <code>X</code> und dem referenzierten Modellteil <code>BrakControl</code> vor und nach dem Merge.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Ablauf stellt eine asynchrone Modellaktualisierung und -verschmelzung dar:</p>\n<ol class=\"fig-list\">\n<li><code>Party Y</code> verwendet eine lokale Kopie/Referenz <code>Model A [remote]</code> von <code>party X</code> und verknüpft eigene Modellelemente (<code>X</code> in <code>Model B</code>) mit <code>BrakControl [remote]</code>.</li>\n<li>Bei <code>party X</code> wird eine Aktualisierung (<code>Update</code>) am Ausgangselement durchgeführt, wodurch <code>BrakControl[source]</code> zu <code>BrakeControl [updated]</code> korrigiert bzw. modifiziert wird.</li>\n<li>Die Traceability (<code>«trace»</code>) stellt die Nachverfolgbarkeit zwischen Ursprungsmodell und Remote-Modell bzw. aktualisiertem Modell sicher.</li>\n<li>Das aktualisierte Modell wird an <code>Party Y</code> übermittelt und dort zu <code>Model A [merged]</code> zusammengeführt, wobei die bestehende interne Referenz von <code>X [merged]</code> auf das umbenannte/aktualisierte Element <code>BrakeControl [merged]</code> erhalten und aufgelöst wird.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Dieses Schaubild verdeutlicht die funktionale Anforderung an AUTOSAR-Autorentools, semantisches Merging und Refactoring (z. B. Umbenennungen von AUTOSAR-Elementen wie Software-Komponenten, Ports oder Interfaces) über verteilte Arbeitsumgebungen hinweg konsistent zu unterstützen. Werkzeuge müssen Identitäten (z. B. über GUIDs / UUIDs oder stabile Pfade) beibehalten, damit Querreferenzen lokaler Artefakte (<code>Model B</code>) bei Aktualisierung extern verwalteter Pakete (<code>Model A</code>) nicht verwaisen (<em>dangling references</em>), sondern automatisiert auf den neuen Versionsstand umgebogen werden.</p>"}], "trans": [{"from": "FIG-c127792a55cc0fae", "to": "FIG-c82b5f1cee12f379", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
